  1	import {
  2	  CalculatorId,
  3	  CalculatorCatalogItem,
  4	} from "@taxkit/calculators/schemas";
  5	import { DocsPublicPagePath } from "@taxkit/content/schemas";
  6	import { Schema } from "effect";
  7	
  8	export const PostHogProjectId = Schema.Int.check(Schema.isGreaterThan(0)).pipe(
  9	  Schema.brand("taxkit/PostHogProjectId")
 10	);
 11	export type PostHogProjectId = typeof PostHogProjectId.Type;
 12	export const CaptureToken = Schema.String.check(
 13	  Schema.isPattern(/^phc_[A-Za-z0-9_-]{20,160}$/u)
 14	).pipe(Schema.brand("taxkit/PublicCaptureToken"));
 15	export const CaptureStage = Schema.String.check(
 16	  Schema.isMaxLength(64),
 17	  Schema.isPattern(/^(?:prod|pr-[1-9]\d*)$/u)
 18	).pipe(Schema.brand("taxkit/AnalyticsCaptureStage"));
 19	export const AnalyticsDisabled = Schema.TaggedStruct("AnalyticsDisabled", {});
 20	export const AnalyticsEnabled = Schema.TaggedStruct("AnalyticsEnabled", {
 21	  environment: Schema.Literals(["production", "controlled-preview"]),
 22	  projectId: PostHogProjectId,
 23	  region: Schema.Literal("us"),
 24	  stage: CaptureStage,
 25	  token: Schema.RedactedFromValue(CaptureToken),
 26	}).check(
 27	  Schema.makeFilter(
 28	    (settings) =>
 29	      settings.environment === "production"
 30	        ? settings.stage === "prod"
 31	        : settings.stage !== "prod",
 32	    {
 33	      message:
 34	        "The analytics environment must match its checked deployment stage.",
 35	    }
 36	  )
 37	);
 38	export const AnalyticsSettings = Schema.Union([
 39	  AnalyticsDisabled,
 40	  AnalyticsEnabled,
 41	]);
 42	export type AnalyticsSettings = typeof AnalyticsSettings.Type;
 43	export const CollectionPolicy = Schema.Literals(["allow", "deny"]);
 44	export type CollectionPolicy = typeof CollectionPolicy.Type;
 45	export const CollectionPolicyHeader = "x-taxkit-collection-policy";
 46	export const CaptureDisposition = Schema.Literals([
 47	  "accepted",
 48	  "disabled",
 49	  "denied",
 50	]);
 51	export type CaptureDisposition = typeof CaptureDisposition.Type;
 52	export const EventId = Schema.String.check(Schema.isUUID(4)).pipe(
 53	  Schema.brand("taxkit/AnalyticsEventId")
 54	);
 55	export const CalculatorAnalyticsName = CalculatorCatalogItem.fields.title
 56	  .check(Schema.isMinLength(1), Schema.isMaxLength(120))
 57	  .pipe(Schema.brand("taxkit/CalculatorAnalyticsName"));
 58	export const CalculatorUse = Schema.Struct({
 59	  calculatorId: CalculatorId,
 60	  calculatorName: CalculatorAnalyticsName,
 61	  collectionPolicy: CollectionPolicy,
 62	});
 63	export type CalculatorUse = typeof CalculatorUse.Type;
 64	export const PagePath = Schema.Union([
 65	  Schema.Literal("/"),
 66	  DocsPublicPagePath,
 67	  Schema.TemplateLiteral(["/calculators/", CalculatorId]),
 68	]).pipe(Schema.brand("taxkit/AnalyticsPagePath"));
 69	export const PageView = Schema.Struct({
 70	  path: PagePath,
 71	  source: Schema.Literals([
 72	    "direct",
 73	    "internal",
 74	    "search",
 75	    "external",
 76	    "unknown",
 77	  ]),
 78	});
 79	export type PageView = typeof PageView.Type;
 80	
 81	// Capture, browser enrichment and provider management keep distinct boundaries.
 82	// This backend wire owner includes no tax inputs, result, visitor or request data.
 83	export const CalculatorCaptureBatch = Schema.Struct({
 84	  api_key: CaptureToken,
 85	  batch: Schema.Tuple([
 86	    Schema.Struct({
 87	      distinct_id: EventId,
 88	      event: Schema.Literal("calculator_used"),
 89	      properties: Schema.Struct({
 90	        $geoip_disable: Schema.Literal(true),
 91	        $process_person_profile: Schema.Literal(false),
 92	        application: Schema.Literal("api"),
 93	        calculator_id: CalculatorUse.fields.calculatorId,
 94	        calculator_name: CalculatorUse.fields.calculatorName,
 95	        project: Schema.Literal("taxkit"),
 96	        schema_version: Schema.Literal(1),
 97	        stage: CaptureStage,
 98	      }),
 99	      timestamp: Schema.DateTimeUtcFromString,
100	      uuid: EventId,
101	    }),
102	  ]),
103	});
104	export const CaptureResponseByteLimit = 65_536;

