 1	import { AnalyticsCaptureError } from "@taxkit/analytics/errors";
 2	import {
 3	  CalculatorAnalyticsName,
 4	  CalculatorUse,
 5	} from "@taxkit/analytics/schemas";
 6	import type { CollectionPolicy } from "@taxkit/analytics/schemas";
 7	import { PublicCalculatorService } from "@taxkit/calculators/service";
 8	import { Array, Context, Effect, Layer, Option, Ref } from "effect";
 9	
10	// The request owns this collector. Registration must omit it so native MCP
11	// cannot retain the first visitor's collection policy or event accumulator.
12	export const ApiCalculatorEvents = Context.Reference<
13	  Option.Option<{
14	    readonly collectionPolicy: CollectionPolicy;
15	    readonly events: Ref.Ref<readonly CalculatorUse[]>;
16	  }>
17	>("@taxkit/api/ApiCalculatorEvents", { defaultValue: Option.none });
18	const ApiCalculatorEventLimit = 64;
19	
20	// One app-owned decorator covers HTTP, RPC and both MCP protocols. It runs
21	// after the checked calculation succeeds, outside its tax-work deadline. The
22	// pure calculator service and local SDK never depend on analytics.
23	export const ApiCalculatorAnalyticsLive = Layer.effect(
24	  PublicCalculatorService,
25	  Effect.gen(function* () {
26	    const calculator = yield* PublicCalculatorService;
27	    return PublicCalculatorService.of({
28	      ...calculator,
29	      calculate: Effect.fn("ApiCalculatorAnalytics.calculate")(
30	        function* (request) {
31	          const result = yield* calculator.calculate(request);
32	          yield* Option.match(yield* ApiCalculatorEvents, {
33	            onNone: () => Effect.void,
34	            onSome: ({ collectionPolicy, events }) =>
35	              collectionPolicy === "deny"
36	                ? Effect.void
37	                : CalculatorAnalyticsName.makeEffect(
38	                    result.calculator.title
39	                  ).pipe(
40	                    Effect.flatMap((calculatorName) =>
41	                      Ref.update(events, (current) =>
42	                        current.length < ApiCalculatorEventLimit
43	                          ? Array.append(
44	                              current,
45	                              CalculatorUse.make({
46	                                calculatorId: result.calculator.calculatorId,
47	                                calculatorName,
48	                                collectionPolicy,
49	                              })
50	                            )
51	                          : current
52	                      )
53	                    ),
54	                    Effect.mapError(
55	                      () =>
56	                        new AnalyticsCaptureError({
57	                          operation: "calculator-use",
58	                          reason: "encoding",
59	                        })
60	                    ),
61	                    Effect.catchTag("AnalyticsCaptureError", () =>
62	                      Effect.logDebug("Calculator analytics name refused")
63	                    )
64	                  ),
65	          });
66	          return result;
67	        }
68	      ),
69	    });
70	  })
71	);

