 1	import * as Doppler from "alchemy/Doppler";
 2	import { retain } from "alchemy/RemovalPolicy";
 3	import * as Secrets from "alchemy/Secrets";
 4	import type { StackSecrets } from "alchemy/Stack";
 5	import { Stage } from "alchemy/Stage";
 6	import { Config, ConfigProvider, Effect } from "effect";
 7	
 8	import { PostHogProject } from "./projects.provider.js";
 9	import {
10	  PostHogManagedName,
11	  PostHogOrganisationId,
12	  ProjectDefinition,
13	} from "./schemas.js";
14	
15	// A single durable stack owns both projects. PR and local graphs never create
16	// or replace a project. The current application graph still collects off.
17	export const declarePostHogProjects = Effect.gen(function* () {
18	  const stage = yield* Stage;
19	  if (stage !== "prod") {
20	    return yield* Effect.fail(
21	      new Config.ConfigError(
22	        new ConfigProvider.SourceError({
23	          message: "PostHog projects require the durable prod stage",
24	        })
25	      )
26	    );
27	  }
28	  const organisation = yield* Config.schema(
29	    PostHogOrganisationId,
30	    "POSTHOG_ORGANISATION_ID"
31	  );
32	  const production = yield* PostHogProject(
33	    "TaxKitProductionProject",
34	    ProjectDefinition.make({
35	      environment: "production",
36	      marker: "taxkit:posthog:production:v1",
37	      name: PostHogManagedName.make("TaxKit Production"),
38	      organisation,
39	      region: "us",
40	    })
41	  ).pipe(retain());
42	  const preview = yield* PostHogProject(
43	    "TaxKitPreviewProject",
44	    ProjectDefinition.make({
45	      environment: "preview",
46	      marker: "taxkit:posthog:preview:v1",
47	      name: PostHogManagedName.make("TaxKit Preview"),
48	      organisation,
49	      region: "us",
50	    })
51	  ).pipe(retain());
52	  return { previewProjectId: preview.id, productionProjectId: production.id };
53	});
54	
55	export const nativePostHogSecrets = (({ stage }: Secrets.SecretsContext) => {
56	  if (stage !== "prod") {
57	    return [Secrets.ProcessEnv({ disabled: true })];
58	  }
59	  return [
60	    Doppler.Secrets({ config: "prd", project: "taxkit" }).layer,
61	    Secrets.ProcessEnv({ disabled: true }),
62	  ];
63	}) satisfies StackSecrets;

