 42	  "https://website.example.com/ingest/e/"
 43	).pipe(
 44	  HttpClientRequest.bodyUint8Array(body, "text/plain"),
 45	  HttpClientRequest.setHeaders({
 46	    authorization: "Bearer PRIVATE9",
 47	    cookie: "private=PRIVATE9",
 48	    origin: "https://website.example.com",
 49	    traceparent: "00-private-trace",
 50	    "x-forwarded-for": "203.0.113.9",
