text((await tools.exec_command({cmd:"python3 - <<'PY'
import subprocess,json,hashlib,os
commit='cc11c6aa04665b4014d14953cd2c1379373b2ef7'
for name in ['2026-10-07-analytics-backend-and-request-policy.json','2026-10-07-website-calculator-collection-policy.json','2026-10-08-retained-posthog-projects.json','2026-10-08-website-event-relay.json']:
    raw=subprocess.check_output(['git','show',f'{commit}:docs/documentation-audit/clean-slate-foundation/{name}'])
    x=json.loads(raw)
    q=x.get('wholeSourceQualification',x.get('completeQualification',x.get('qualification',{})))
    print(name, json.dumps({'status':x.get('status',x.get('outcome')),'qualification':q if len(json.dumps(q))<1500 else {'keys':list(q.keys()),'source':q.get('candidateCommit',q.get('qualifiedSourceCommit')), 'checks':[{'stage':c.get('stage'), 'exit':c.get('exitCode')} for c in q.get('checks',[]) if isinstance(c,dict)]}}))
    checked=[]
    def visit(v):
      if isinstance(v,dict):
        digest=v.get('logSha256')
        path=v.get('log',v.get('logArtifact'))
        if digest and path:
          path=path if path.startswith('/') else '/private/tmp/'+path
          if os.path.isfile(path):
            checked.append({'artifact':os.path.basename(path),'match':hashlib.sha256(open(path,'rb').read()).hexdigest()==digest})
        for value in v.values(): visit(value)
      elif isinstance(v,list):
        for value in v: visit(value)
    visit(x)
