 42	export const PostHogProjectProvider = Provider.effect(
 43	  PostHogProject,
 44	  Effect.gen(function* () {
 45	    const management = yield* PostHogManagement;
 46	    return {
 47	      delete: Effect.fn("PostHogProject.delete")(() =>
 48	        Effect.fail(
 49	          new PostHogManagementError({
 50	            operation: "project-lifecycle",
 51	            reason: "retained-project",
 52	          })
 53	        )
 54	      ),
 55	      diff: Effect.fn("PostHogProject.diff")(function* ({
 56	        olds,
 57	        news,
 58	        output,
 59	      }) {
 60	        if (!Diff.isResolved(news)) {
 61	          return;
 62	        }
 63	        const desired = yield* ProjectDefinition.makeEffect(news).pipe(
 64	          Effect.mapError(
 65	            () =>
 66	              new PostHogManagementError({
 67	                operation: "project-lifecycle",
 68	                reason: "invalid-configuration",
 69	              })
 70	          )
 71	        );
 72	        const previous = yield* ProjectDefinition.makeEffect(olds).pipe(
 73	          Effect.mapError(
 74	            () =>
 75	              new PostHogManagementError({
 76	                operation: "project-lifecycle",
 77	                reason: "invalid-response",
 78	              })
 79	          )
 80	        );
 81	        yield* requireSameOwner(previous, desired);
 82	        return yield* Option.match(Option.fromNullishOr(output), {
 83	          onNone: () =>
 84	            Effect.fail(
 85	              new PostHogManagementError({
 86	                operation: "project-lifecycle",
 87	                reason: "retained-project-missing",
 88	              })
 89	            ),
 90	          onSome: (raw) =>
 91	            Effect.gen(function* () {
 92	              const current = yield* ManagedProject.makeEffect(raw).pipe(
 93	                Effect.mapError(
 94	                  () =>
