 30	    "POSTHOG_ORGANISATION_ID"
 31	  );
 32	  const project = yield* PostHogProject(
 33	    "TaxKitProject",
 34	    ProjectDefinition.make({
 35	      marker: "taxkit:posthog:shared:v1",
 36	      name: PostHogManagedName.make("TaxKit"),
 37	      organisation,
 38	      region: "us",
 39	    })
 40	  ).pipe(retain());
 41	  return { projectId: project.id };
 42	});
