 44	export const nativePostHogSecrets = (({ stage }: Secrets.SecretsContext) => {
 45	  if (stage !== "prod") {
 46	    return [Secrets.ProcessEnv({ disabled: true })];
 47	  }
 48	  return [
 49	    Doppler.Secrets({ config: "prd", project: "taxkit" }).layer,
 50	    Secrets.ProcessEnv({ disabled: true }),
 51	  ];
 52	}) satisfies StackSecrets;

