          generation.status === "replacing" ||
          generation.status === "replaced"
        ) {
          generation = generation.old;
          for (const dep of generation.downstream) downstream.add(dep);
        }
        // NOTE: an attr-less row (interrupted create) is NOT recovered
        // here. Apply's `deleteResource` performs the authoritative
        // read-then-delete recovery — it also covers replaced-chain
        // old generations that never pass through plan, and routes
        // `Unowned` results away from `provider.delete`.
        return [
          fqn,
          {
            action: oldState.removalPolicy === "retain" ? "orphaned" : "delete",
            state: oldState,
            provider: provider,
            mode: oldState.providerMode,
            resource: {
              Namespace: oldState.namespace,
              FQN: fqn,
              LogicalId: logicalId,
              Type: oldState.resourceType,
              Attributes: oldState.attr,
              Props: oldState.props,
              Binding: undefined!,
              Provider: Provider(resourceType),
              RemovalPolicy: oldState.removalPolicy,
              Adopt: undefined,
              RequiresImplementation: undefined,
              Mode: oldState.providerMode,
      typeof key === "string" &&
      key.includes(".") &&
      isProviderService(value)
    ) {
      registered.set(key, value);
    }
  }
  const included = include?.length ? picomatch([...include]) : () => true;
  const excluded = exclude?.length ? picomatch([...exclude]) : () => false;
  const output: DiscoveredProvider[] = [];
  for (const [id, registration] of registered) {
    if (!included(id) || excluded(id)) continue;
    if (mode === "local" && registration.modes === undefined) continue;
    const provider = yield* providerForMode(registration, mode);
    if (provider.nuke?.singleton || provider.nuke?.skip) continue;
    output.push({ id, provider });
